/*
 * A267776  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 209" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A267776
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   a(n) = 1 if there exists k∈ℕ with k(k+2) ≤ n ≤ k(k+4); otherwise
 *            a(n)=0
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdbool.h>

/* integer square root of n (floor), using 128‑bit arithmetic */
static idx_t integer_sqrt(idx_t n) {
    idx_t low = 0, high = (idx_t)1;
    /* find an upper bound for sqrt(n) */
    while ((__int128)high * high <= n) {
        if (high > (idx_t)(-1) >> 1) { /* avoid overflow */
            high = (idx_t)(-1) >> 1;
            break;
        }
        high <<= 1;
    }
    low = high >> 1;
    /* binary search between low and high-1 */
    while (low <= high) {
        idx_t mid = low + ((high - low) >> 1);
        __int128 mid2 = (__int128)mid * mid;
        if (mid2 == n) {
            return mid;
        } else if (mid2 < n) {
            low = mid + 1;
        } else {
            if (mid == 0) break;
            high = mid - 1;
        }
    }
    return high; /* floor(sqrt(n)) */
}

/* find the largest k such that k(k+2) <= n */
static idx_t find_k(idx_t n) {
    idx_t low = 0;
    idx_t high = integer_sqrt(n) + 1; /* k never exceeds sqrt(n)+1 */
    idx_t ans = 0;
    while (low <= high) {
        idx_t mid = low + ((high - low) >> 1);
        __int128 val = (__int128)mid * (mid + 2);
        if (val <= n) {
            ans = mid;
            low = mid + 1;
        } else {
            if (mid == 0) break;
            high = mid - 1;
        }
    }
    return ans;
}

seq_t a(idx_t n) {
    idx_t k = find_k(n);
    __int128 upper = (__int128)k * (k + 4);
    return (upper >= n) ? (seq_t)1 : (seq_t)0;
}
